use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigWebauthnEnabledAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigWebauthnEnabledAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isWebauthnEnabled returns null on a freshly created holder.
     */
    public function testWebauthnEnabledNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWebauthnEnabledAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isWebauthnEnabledAssigned());
        $this->assertNull($holder->isWebauthnEnabled());
    }
}
class ImplWithTenantConfigWebauthnEnabledAttributeHolderUnitTest
{
    use TenantConfigWebauthnEnabledAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedWebauthnEnabledRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultWebauthnEnabled();
    }
}
